create table if not exists sigov.tributario_carne_emissao (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint, exercicio_id bigint, contribuinte_id bigint, cadastro_imobiliario_id bigint, cadastro_economico_id bigint, lancamento_id bigint, guia_id bigint, referencia_id bigint, codigo varchar(120), numero bigint, ano integer, tipo varchar(80), status varchar(40) not null default 'RASCUNHO', descricao text, justificativa text, quantidade numeric(18,4), valor numeric(18,2), competencia date, prazo_at timestamptz, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb, correlation_id uuid not null default gen_random_uuid(), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz, deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint);
